(function(){"use strict";function init(){var mobile=window.matchMedia("(max-width:700px)");document.querySelectorAll('.stage-quick-switcher[id^="sqs-"]').forEach(function(switcher){var stage=switcher.id.slice(4);var slot=document.getElementById("selected-hotel-slot-"+stage);var list=switcher.querySelector(".sqs-buttons");if(!slot||!list||slot.closest(".hotel-tab-shell"))return;var shell=document.createElement("div");shell.className="hotel-tab-shell";slot.before(shell);var previousPanel=switcher.closest(".t-bubble");shell.appendChild(switcher);if(previousPanel&&!previousPanel.children.length&&!previousPanel.textContent.trim())previousPanel.remove();shell.appendChild(slot);slot.classList.add("hotel-tab-panel");slot.setAttribute("role","tabpanel");slot.tabIndex=0;list.setAttribute("role","tablist");function syncOrientation(){list.setAttribute("aria-orientation",mobile.matches?"horizontal":"vertical")}syncOrientation();mobile.addEventListener("change",syncOrientation);var label=switcher.querySelector(".sqs-label");list.setAttribute("aria-label",label?label.textContent.trim():"Výběr hotelu");var buttons=Array.from(list.querySelectorAll(".sqs-btn"));buttons.forEach(function(button){var variant=button.getAttribute("data-variant");var text=button.textContent.trim();button.type="button";button.id="hotel-tab-"+stage+"-"+variant;button.setAttribute("role","tab");button.setAttribute("aria-controls",slot.id);button.setAttribute("aria-label",text);button.title=text;button.setAttribute("aria-selected",String(button.classList.contains("active")));button.tabIndex=button.classList.contains("active")?0:-1;if(button.classList.contains("active"))slot.setAttribute("aria-labelledby",button.id);var key=document.createElement("span");key.className="hotel-tab-key";key.setAttribute("aria-hidden","true");key.textContent=variant;var caption=document.createElement("span");caption.className="hotel-tab-caption";caption.textContent=text;button.replaceChildren(key,caption)});list.addEventListener("keydown",function(event){var index=buttons.indexOf(event.target.closest(".sqs-btn"));if(index<0)return;var next;if(event.key===(mobile.matches?"ArrowRight":"ArrowDown"))next=(index+1)%buttons.length;else if(event.key===(mobile.matches?"ArrowLeft":"ArrowUp"))next=(index+buttons.length-1)%buttons.length;else if(event.key==="Home")next=0;else if(event.key==="End")next=buttons.length-1;else return;event.preventDefault();event.stopPropagation();buttons[next].focus({preventScroll:true})})})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();